    const nextStartTimeRef = useRef<number>(0);
    const sessionRef = useRef<any>(null);
    const micStreamRef = useRef<MediaStream | null>(null);
    const processorRef = useRef<ScriptProcessorNode | null>(null);

    const handlePillPointersDown = (e: React.PointerEvent) => {
        if (e.button !== 0 && e.pointerType === 'mouse') return;
        e.preventDefault();
        const el = e.currentTarget as HTMLElement;
        const rect = el.getBoundingClientRect();
        const offsetX = e.clientX - rect.left;
        const offsetY = e.clientY - rect.top;
        const startX = e.clientX;
        const startY = e.clientY;
        isDraggingPill.current = false;
        const onPointerMove = (ev: PointerEvent) => {
             const dx = ev.clientX - startX;
             const dy = ev.clientY - startY;
             if (Math.abs(dx) > 3 || Math.abs(dy) > 3) isDraggingPill.current = true;
             let newX = ev.clientX - offsetX;
             let newY = ev.clientY - offsetY;
             const maxX = window.innerWidth - rect.width;
             const maxY = window.innerHeight - rect.height;
             newX = Math.max(0, Math.min(newX, maxX));
             newY = Math.max(0, Math.min(newY, maxY));
             setPillPos({ x: newX, y: newY });
        };
        const onPointerUp = () => {
            document.removeEventListener('pointermove', onPointerMove);
            document.removeEventListener('pointerup', onPointerUp);
        };
        document.addEventListener('pointermove', onPointerMove);
        document.addEventListener('pointerup', onPointerUp);
    };

    const handleRoomViewFeed = (id: string) => {
        showToast("请在校友圈主页查看个人动态");
    };

    useEffect(() => {
      setParticipants(prev => prev.map(p => {
        if (p.id === 'pastor') return { ...p, isSpeaking: isAiSpeaking };
        if (p.id === 'me') return { ...p, isSpeaking: isMicOn };
        return p;
      }));
    }, [isAiSpeaking, isMicOn]);

    useEffect(() => {
      const isHidden = localStorage.getItem(`amas_hide_guide_${currentType}`);
      if (!isHidden) {
        setShowGuide(true);
      }
    }, [currentType]);

    const connectToGemini = async () => {
      try {
        setIsAiLoading(true);
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        aiClientRef.current = ai;
        const AudioContextClass = window.AudioContext || (window as any).webkitAudioContext;
        audioContextRef.current = new AudioContextClass({ sampleRate: SAMPLE_RATE });
        inputAudioContextRef.current = new AudioContextClass({ sampleRate: 16000 });
        const stream = await navigator.mediaDevices.getUserMedia({ audio: { channelCount: 1, sampleRate: 16000 }});
        micStreamRef.current = stream;
        const sessionPromise = ai.live.connect({
          model: 'gemini-2.5-flash-native-audio-preview-09-2025',
          callbacks: {
            onopen: () => {
              setIsAiConnected(true);
              setIsAiLoading(false);
              showToast("已连接到语音牧师");
              const source = inputAudioContextRef.current!.createMediaStreamSource(stream);
              const processor = inputAudioContextRef.current!.createScriptProcessor(4096, 1, 1);
              processorRef.current = processor;
              processor.onaudioprocess = (e) => {
                if (!isMicOn) return; 
                const inputData = e.inputBuffer.getChannelData(0);
                const pcmData = floatTo16BitPCM(inputData);
                const base64Data = arrayBufferToBase64(pcmData.buffer);
                sessionPromise.then(session => {
                   session.sendRealtimeInput({ media: { mimeType: "audio/pcm;rate=16000", data: base64Data } } as any);
                });
              };
              source.connect(processor);
              processor.connect(inputAudioContextRef.current!.destination);
            },
            onmessage: async (message: LiveServerMessage) => {
               const audioData = message.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
               if (audioData) {
                  setIsAiSpeaking(true);
                  const ctx = audioContextRef.current!;
                  const audioBytes = base64ToUint8Array(audioData);
                  const audioBuffer = ctx.createBuffer(1, audioBytes.length / 2, SAMPLE_RATE);
                  const channelData = audioBuffer.getChannelData(0);
                  const view = new DataView(audioBytes.buffer);
                  for(let i=0; i < audioBytes.length / 2; i++){
                      const pcm16 = view.getInt16(i * 2, true);
                      channelData[i] = pcm16 / 32768.0;
                  }
                  const source = ctx.createBufferSource();
                  source.buffer = audioBuffer;
                  source.connect(ctx.destination);
                  const now = ctx.currentTime;
                  const start = Math.max(now, nextStartTimeRef.current);
                  source.start(start);
                  nextStartTimeRef.current = start + audioBuffer.duration;
                  source.onended = () => {
                     if (ctx.currentTime >= nextStartTimeRef.current - 0.1) setIsAiSpeaking(false);
                  };
               }
               if (message.serverContent?.turnComplete) setIsAiSpeaking(false);
            },
            onclose: () => { setIsAiConnected(false); setIsAiSpeaking(false); },
            onerror: (e) => { setIsAiConnected(false); setIsAiLoading(false); setIsAiSpeaking(false); }
          },
          config: {
            responseModalities: [Modality.AUDIO],
            systemInstruction: "You are Pastor Li, a wise and caring pastor. Listen to students, offer biblical encouragement, and pray for them. Use Chinese language.",
            speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Puck' } } }
          }
        });
        sessionRef.current = sessionPromise;
      } catch (error) {
        setIsAiLoading(false);
        showToast("连接失败，请重试");
      }
    };

    const disconnectFromGemini = () => {
       if (micStreamRef.current) micStreamRef.current.getTracks().forEach(t => t.stop());
       if (processorRef.current) processorRef.current.disconnect();
       if (audioContextRef.current?.state !== 'closed') audioContextRef.current?.close();
       if (inputAudioContextRef.current?.state !== 'closed') inputAudioContextRef.current?.close();
       setIsAiConnected(false);
       setIsAiSpeaking(false);
    };

    useEffect(() => {
      if (chatContainerRef.current) {
        chatContainerRef.current.scrollTop = chatContainerRef.current.scrollHeight;
      }
    }, [roomChats]);

    const handleSendChat = () => {
      if (!chatInput.trim()) return;
      setRoomChats([...roomChats, { id: `m-${Date.now()}`, user: '我', userAvatar: 'https://picsum.photos/200/200?random=me', text: chatInput, type: 'text' }]);
      setChatInput("");
    };

    const handleQuickResponse = (item: {text: string, icon: string}) => {
      setRoomChats(prev => [...prev, { 
        id: `m-${Date.now()}`, 
        user: '我', 
        userAvatar: me?.avatar, 
        text: `${item.text} ${item.icon}`, 
        type: 'text' 
      }]);
      triggerReaction(item.icon, item.text);
      setShowResponsePanel(false);
