    };

    const triggerGiftAnimation = (gift: any) => {
      const id = Date.now();
      const count = gift.cost >= 50 ? 15 : (gift.cost >= 20 ? 5 : 1);
      const newEffects: GiftEffect[] = Array.from({ length: count }).map((_, i) => ({
        id: id + i,
        icon: gift.icon,
        type: gift.effect,
        color: gift.theme,
        x: Math.random() * 60 + 20, 
