        setActiveGiftEffects(prev => prev.filter(e => e.id < id || e.id >= id + count));
      }, 4000);
    };

    const handleSendGift = (gift: any) => {
      setRoomChats([...roomChats, { 
        id: `g-${Date.now()}`, 
        user: '我', 
        userAvatar: 'https://picsum.photos/200/200?random=me', 
