  const handleCreateGroupChat = (name: string, members: string[]) => { const newGroupId = `g-${Date.now()}`; const newGroup: Conversation = { id: newGroupId, userId: newGroupId, userName: name, userAvatar: `https://ui-avatars.com/api/?name=${encodeURIComponent(name)}&background=random&color=fff`, isOnline: false, lastMessage: '群组已创建，开始聊天吧', time: '刚刚', unread: 0, role: 'Group', isGroup: true }; setConversations([newGroup, ...conversations]); try { const savedGroupsStr = localStorage.getItem('amas_custom_groups'); const savedGroups: Conversation[] = savedGroupsStr ? JSON.parse(savedGroupsStr) : []; savedGroups.push(newGroup); localStorage.setItem('amas_custom_groups', JSON.stringify(savedGroups)); } catch (e) { console.error("Failed to save group", e); } setShowCreateGroup(false); showToast(`群组 "${name}" 创建成功`); if (directoryTab !== 'groups') { setDirectoryTab('groups'); } };
  const handleJoinRoom = (room: Room) => { if (room.isCustom && room.hostId === 'me') { setActiveVoiceRoom(room); setIsRoomMinimized(false); return; } if (room.password) { setPendingRoom(room); setInputPassword(""); setShowPasswordPrompt(true); } else { setActiveVoiceRoom(room); setIsRoomMinimized(false); } };
