  const handleEndRoom = () => { setMyRoom(null); setActiveVoiceRoom(null); showToast("房间已结束"); };
  const handleCreatePost = (content: string, images: string[], linkedCourseId?: string) => { const newPost: CommunityPost = { id: `post-${Date.now()}`, userId: 'me', userName: MOCK_USER.name, userAvatar: MOCK_USER.avatar, userRole: MOCK_USER.degree, content: content, images: images, timestamp: '刚刚', likes: 0, comments: 0, likedByMe: false, likedByUsers: [], category: 'general', connectionStatus: 'none', linkedCourseId: linkedCourseId }; setPosts([newPost, ...posts]); setShowCreateMoment(false); showToast("发布成功！"); };
  const handleLikePost = (postId: string) => { setPosts(posts.map(post => { if (post.id === postId) { const isLiked = post.likedByMe; let newLikers = post.likedByUsers || []; if (isLiked) { newLikers = newLikers.filter(u => u.id !== 'me'); } else { newLikers = [{ id: 'me', name: MOCK_USER.name, avatar: MOCK_USER.avatar }, ...newLikers]; } return { ...post, likes: newLikers.length, likedByMe: !isLiked, likedByUsers: newLikers }; } return post; })); };
