        giftData: { name: gift.name, icon: gift.icon, theme: gift.theme }
      }]);
      setShowGiftPanel(false);
      // Trigger animation
      const id = Date.now();
      const count = gift.cost >= 50 ? 15 : 5;
      const newEffects: GiftEffect[] = Array.from({ length: count }).map((_, i) => ({
        id: id + i,
        icon: gift.icon,
        type: gift.effect,
        color: gift.theme,
        x: Math.random() * 60 + 20, 
        y: Math.random() * 40 + 30
      }));
      setActiveGiftEffects(prev => [...prev, ...newEffects]);
      setTimeout(() => {
        setActiveGiftEffects(prev => prev.filter(e => e.id < id || e.id >= id + count));
      }, 4000);
    };

    const handleLessonClick = (p: Participant) => {
        if (p.id === 'me') return;
        if (!canManage) return;
        setSelectedParticipant(p);
        setShowUserManageModal(true);
    };

    // 筛选出上麦者，限制最大显示10人
    const stageParticipants = participants.filter(p => p.role !== 'listener').slice(0, 10);
    const leftParticipants = stageParticipants.slice(0, 5);
    const rightParticipants = stageParticipants.slice(5, 10);
    const listeners = participants.filter(p => p.role === 'listener');

    const renderCenterContent = () => {
        switch(currentType) {
            case 'prayer':
                return (
                    <div className="bg-[#3b0b1a]/90 border border-[#5c1a2e] rounded-2xl overflow-hidden shadow-2xl backdrop-blur-sm h-full flex flex-col">
                        <div className="bg-[#4d0f22] px-4 py-2 flex items-center border-b border-[#5c1a2e]">
                            <HandHeart size={14} className="mr-2 text-rose-400"/> 
                            <span className="text-[10px] font-bold text-rose-200 uppercase tracking-widest">祷告墙</span>
                        </div>
                        <div className="p-4 flex-1 overflow-y-auto custom-scrollbar h-full">
                            {isEditingPrayerWall ? (
                                <textarea
                                    value={prayerWallContent}
                                    onChange={(e) => setPrayerWallContent(e.target.value)}
                                    className="w-full h-full bg-white/5 rounded-xl p-3 text-xs text-white outline-none resize-none font-serif leading-relaxed"
                                    autoFocus
                                    onBlur={() => setIsEditingPrayerWall(false)}
                                />
                            ) : (
                                <div onClick={() => me?.role === 'host' && setIsEditingPrayerWall(true)} className="text-sm text-rose-50/90 leading-relaxed space-y-3 font-serif">
                                    {prayerWallContent.split('\n').map((line, i) => <p key={i}>{line}</p>)}
                                </div>
                            )}
                        </div>
                    </div>
                );
            case 'praise':
                return (
                    <div className="bg-amber-900/40 border border-amber-500/20 rounded-2xl overflow-hidden shadow-2xl backdrop-blur-sm h-full flex flex-col items-center justify-center p-6">
                        <div className="w-16 h-16 bg-amber-500/20 rounded-full flex items-center justify-center mb-4 animate-pulse">
                            <Music size={32} className="text-amber-400" />
                        </div>
                        <div className="text-center">
                            <h3 className="text-sm font-bold text-amber-50 mb-1">{currentSong.title}</h3>
                            <p className="text-[10px] text-amber-200/60 mb-4">{currentSong.artist}</p>
                            <div className="flex items-center space-x-4 justify-center">
                                <button className="p-2 rounded-full bg-white/5 text-white/40"><SkipForward className="rotate-180" size={16} /></button>
                                <button onClick={() => setIsPlaying(!isPlaying)} className="p-3 rounded-full bg-amber-500 text-amber-950">{isPlaying ? <Pause size={20} fill="currentColor" /> : <Play size={20} fill="currentColor" />}</button>
                                <button className="p-2 rounded-full bg-white/5 text-white/40"><SkipForward size={16} /></button>
                            </div>
                        </div>
                    </div>
                );
            case 'bible':
                return (
                    <div className="bg-blue-900/40 border border-blue-500/20 rounded-2xl overflow-hidden shadow-2xl backdrop-blur-sm h-full flex flex-col">
                        <div className="bg-blue-800/40 px-4 py-2 flex items-center justify-between border-b border-blue-500/20">
                            <span className="text-[10px] font-bold text-blue-200">{currentBibleChapter.book} {currentBibleChapter.chapter}章</span>
                            <button onClick={() => setShowBibleSelector(true)} className="text-[10px] bg-blue-500 text-white px-2 py-0.5 rounded">切换</button>
                        </div>
                        <div className="p-4 flex-1 overflow-y-auto custom-scrollbar space-y-3">
                            {currentBibleChapter.content.map((verse, i) => (
                                <p key={i} className="text-xs text-blue-50/80 font-serif leading-relaxed">{verse}</p>
                            ))}
                        </div>
                    </div>
                );
            case 'preaching':
                return (
                    <div className="bg-purple-900/40 border border-purple-500/20 rounded-2xl overflow-hidden shadow-2xl backdrop-blur-sm h-full flex flex-col">
                         <div className="bg-purple-800/40 px-4 py-2 flex items-center border-b border-purple-500/20">
                            <FileText size={14} className="mr-2 text-purple-400"/> 
                            <span className="text-[10px] font-bold text-purple-200 uppercase tracking-widest">讲道大纲</span>
                        </div>
                        <div className="p-4 flex-1 overflow-y-auto custom-scrollbar">
                             <textarea 
                                value={sermonNotes} 
                                onChange={(e) => setSermonNotes(e.target.value)} 
                                className="w-full h-full bg-transparent text-xs text-purple-50/90 font-serif leading-relaxed outline-none resize-none"
                                placeholder="输入讲道重点..."
                             />
                        </div>
                    </div>
                );
            default: return null;
        }
    };

    return createPortal(
      <div className={`fixed inset-0 z-[9999] ${getBgGradient()} animate-fade-in flex flex-col text-white h-[100dvh]`}>
        {/* Header */}
        <div className="relative h-14 flex justify-between items-center px-4 pt-safe-top z-20 shrink-0">
          <button onClick={() => setIsRoomMinimized(true)} className="p-2 -ml-2 rounded-full hover:bg-white/10">
            <Minimize2 size={20} className="text-white/80" />
          </button>
          <div className="text-center">
            <h2 className="font-bold text-xs tracking-wider">{activeVoiceRoom.label}</h2>
            <div className="flex items-center justify-center space-x-1 mt-0.5">
               <span className="w-1 h-1 rounded-full bg-emerald-400 animate-pulse"></span>
               <span className="text-[9px] text-emerald-400 font-bold uppercase tracking-widest">{participants.length}人在线</span>
            </div>
          </div>
          <button onClick={() => setShowRoomInfo(true)} className="p-2 -mr-2 rounded-full hover:bg-white/10">
             <MoreHorizontal size={20} className="text-white/80" />
          </button>
        </div>

        {/* Main Content Area */}
        <div className="flex-1 relative w-full overflow-hidden flex flex-col p-4">
            {useSequenceLayout ? (
                <div className="flex-1 flex flex-row items-stretch justify-between gap-4">
                    {/* Left Mic Column (5 seats) */}
                    <div className="flex flex-col justify-between py-2 space-y-4">
                        {leftParticipants.map((p, idx) => (
                            <div key={p.id} onClick={() => handleLessonClick(p)} className="flex flex-col items-center relative group">
                                <div className={`relative w-12 h-12 p-[2px] rounded-squircle ${p.id === 'me' ? 'bg-gradient-to-tr from-yellow-400 to-red-600 shadow-lg' : 'bg-white/10'}`}>
                                    <img src={p.avatar} className="w-full h-full object-cover border-2 border-slate-900 rounded-squircle" />
                                    {p.isSpeaking && (
                                        <div className="absolute inset-0 rounded-squircle border-2 border-emerald-400 animate-ping pointer-events-none"></div>
                                    )}
                                    <div className="absolute -top-1 -right-1 bg-white/20 backdrop-blur rounded-full w-4 h-4 flex items-center justify-center text-[8px] font-bold">{idx + 1}</div>
                                </div>
                                <span className="text-[9px] text-white/60 font-bold mt-1 max-w-[50px] truncate text-center">{p.name}</span>
                            </div>
                        ))}
                        {leftParticipants.length < 5 && Array.from({ length: 5 - leftParticipants.length }).map((_, i) => (
                             <div key={`empty-l-${i}`} className="w-12 h-12 rounded-squircle border-2 border-dashed border-white/10 flex items-center justify-center text-white/5 opacity-50"><Mic size={16}/></div>
                        ))}
                    </div>

                    {/* Central Content Area */}
                    <div className="flex-1 h-full min-w-0">
                        {renderCenterContent()}
                    </div>

                    {/* Right Mic Column (5 seats) */}
                    <div className="flex flex-col justify-between py-2 space-y-4">
                        {rightParticipants.map((p, idx) => (
                            <div key={p.id} onClick={() => handleLessonClick(p)} className="flex flex-col items-center relative group">
                                <div className={`relative w-12 h-12 p-[2px] rounded-squircle ${p.id === 'me' ? 'bg-gradient-to-tr from-yellow-400 to-red-600 shadow-lg' : 'bg-white/10'}`}>
                                    <img src={p.avatar} className="w-full h-full object-cover border-2 border-slate-900 rounded-squircle" />
                                    {p.isSpeaking && (
                                        <div className="absolute inset-0 rounded-squircle border-2 border-emerald-400 animate-ping pointer-events-none"></div>
                                    )}
                                    <div className="absolute -top-1 -right-1 bg-white/20 backdrop-blur rounded-full w-4 h-4 flex items-center justify-center text-[8px] font-bold">{idx + 6}</div>
                                </div>
                                <span className="text-[9px] text-white/60 font-bold mt-1 max-w-[50px] truncate text-center">{p.name}</span>
                            </div>
                        ))}
                        {rightParticipants.length < 5 && Array.from({ length: 5 - rightParticipants.length }).map((_, i) => (
                             <div key={`empty-r-${i}`} className="w-12 h-12 rounded-squircle border-2 border-dashed border-white/10 flex items-center justify-center text-white/5 opacity-50"><Mic size={16}/></div>
                        ))}
                    </div>
                </div>
            ) : (
                /* Fellowship Room: Standard Grid Layout */
                <div className="flex-1 grid grid-cols-3 gap-6 items-center justify-items-center overflow-y-auto scrollbar-hide py-6">
                    {participants.filter(p => p.role !== 'listener').map(p => (
                        <div key={p.id} onClick={() => handleLessonClick(p)} className="flex flex-col items-center group relative cursor-pointer">
                            <div className="relative w-20 h-20 mb-3">
                                <div className={`w-full h-full p-1 rounded-squircle transition-all ${p.isSpeaking ? 'bg-gradient-to-tr from-emerald-400 to-blue-400 scale-110 shadow-lg shadow-emerald-500/20' : 'bg-white/10 hover:bg-white/20'}`}>
                                    <img src={p.avatar} className="w-full h-full rounded-squircle object-cover border-2 border-slate-900" />
                                </div>
                                <span className={`absolute -bottom-1 -right-1 rounded-full p-1.5 shadow-lg ${p.isSpeaking ? 'bg-white text-emerald-600' : 'bg-slate-800 text-white'}`}>
                                    {p.isSpeaking ? <Mic size={12} fill="currentColor" /> : <MicOff size={12} />}
                                </span>
                            </div>
                            <span className="text-xs font-bold text-white/80">{p.name}</span>
                        </div>
                    ))}
                    {isOnStage && participants.filter(p => p.role !== 'listener').length < 12 && (
                         <button className="flex flex-col items-center animate-pulse">
                            <div className="w-20 h-20 rounded-squircle border-2 border-dashed border-white/20 flex items-center justify-center text-white/20 hover:text-white/40 transition-colors">
                                <Plus size={32} />
                            </div>
                            <span className="text-[10px] text-white/20 font-bold mt-2 uppercase tracking-widest">邀请上麦</span>
                         </button>
                    )}
                </div>
            )}

            {/* Bottom Section: Chat & Controls */}
            <div className="h-48 shrink-0 flex flex-col mt-4">
                <div ref={chatContainerRef} className="flex-1 overflow-y-auto px-2 pb-2 scrollbar-hide" style={{ maskImage: 'linear-gradient(to bottom, transparent 0%, black 15%)' }}>
                    <div className="space-y-2 flex flex-col justify-end min-h-full">
                        {roomChats.map(msg => (
                            <div key={msg.id} className={`flex w-full ${msg.user === '我' ? 'justify-end' : 'justify-start'} animate-fade-in-up`}>
                                <div className={`flex max-w-[85%] gap-2 ${msg.user === '我' ? 'flex-row-reverse' : 'flex-row'}`}>
                                    <img src={msg.userAvatar || `https://ui-avatars.com/api/?name=${msg.user}`} className="w-6 h-6 rounded-full shrink-0 border border-white/10" />
                                    <div className={`px-3 py-1.5 rounded-2xl text-[11px] backdrop-blur-md border ${msg.user === '我' ? 'bg-blue-600/30 border-blue-400/20' : 'bg-white/5 border-white/10'}`}>
                                        <span className="text-white/90">{msg.text}</span>
                                    </div>
                                </div>
                            </div>
                        ))}
                    </div>
                </div>

                <div className="flex items-center space-x-3 py-3 border-t border-white/5">
                    <button onClick={() => setShowMenu(!showMenu)} className="w-10 h-10 rounded-full bg-white/5 flex items-center justify-center active:scale-90 transition-transform"><Plus size={20} /></button>
                    <div className="flex-1 bg-white/5 rounded-full px-4 h-10 flex items-center border border-white/10 focus-within:border-white/30 transition-all">
                        <input value={chatInput} onChange={e => setChatInput(e.target.value)} onKeyDown={e => e.key === 'Enter' && (setRoomChats([...roomChats, {id: Date.now().toString(), user: '我', text: chatInput, userAvatar: MOCK_USER.avatar}]), setChatInput(''))} placeholder="输入文字..." className="bg-transparent border-none outline-none text-sm w-full placeholder-white/20" />
                    </div>
                    <button onClick={() => setIsMicOn(!isMicOn)} className={`w-10 h-10 rounded-full flex items-center justify-center transition-all ${isMicOn ? 'bg-blue-600 shadow-lg shadow-blue-500/30' : 'bg-white/5 text-white/40'}`}>
                        {isMicOn ? <Mic size={20} /> : <MicOff size={20} />}
                    </button>
                    <button onClick={() => setShowGiftPanel(true)} className="w-10 h-10 rounded-full bg-gradient-to-br from-amber-400 to-orange-600 text-white shadow-lg active:scale-90 transition-transform"><Gift size={20} /></button>
                    <button onClick={() => triggerReaction()} className="w-10 h-10 rounded-full bg-rose-600 text-white flex items-center justify-center active:scale-90 transition-transform"><Heart size={20} fill="currentColor" /></button>
                </div>
            </div>
        </div>

        {/* Modals & Overlays */}
        <GiftAnimationLayer activeEffects={activeGiftEffects} />
        {showGiftPanel && (
             <div className="absolute bottom-0 left-0 right-0 bg-[#12121e] rounded-t-3xl border-t border-white/10 p-6 z-[100] animate-slide-up">
                <div className="flex justify-between items-center mb-6"><h3 className="font-bold">送出礼物</h3><button onClick={() => setShowGiftPanel(false)}><X size={20}/></button></div>
                <div className="grid grid-cols-5 gap-4">
                    {GIFT_ITEMS.map(gift => (
                        <button key={gift.id} onClick={() => handleSendGift(gift)} className="flex flex-col items-center space-y-2 hover:scale-110 transition-transform">
                            <span className="text-3xl">{gift.icon}</span>
                            <span className="text-[10px] opacity-60 text-center">{gift.name}</span>
                        </button>
                    ))}
                </div>
             </div>
        )}

        {showRoomInfo && (
            <div className="absolute inset-0 bg-black/80 backdrop-blur-sm flex items-center justify-center p-6 z-[200]" onClick={() => setShowRoomInfo(false)}>
                <div className="bg-white text-slate-900 w-full max-w-xs rounded-2xl p-6 animate-scale-in" onClick={e => e.stopPropagation()}>
                    <div className="flex justify-between items-center mb-6"><h3 className="font-bold">房间设置</h3><button onClick={() => setShowRoomInfo(false)}><X size={20}/></button></div>
                    <div className="space-y-4">
                        <button onClick={() => { setShowGuide(true); setShowRoomInfo(false); }} className="w-full text-left p-3 rounded-xl bg-slate-50 flex items-center"><HelpCircle size={18} className="mr-3 text-blue-600" />查看指南</button>
                        <button onClick={() => { disconnectFromGemini(); setActiveVoiceRoom(null); }} className="w-full text-left p-3 rounded-xl bg-rose-50 text-rose-600 flex items-center"><LogOut size={18} className="mr-3" />离开房间</button>
                    </div>
                </div>
            </div>
        )}
      </div>
    );
};

const CreateRoomModal: React.FC<{onClose: () => void, onCreate: (name: string, type: RoomType, password?: string) => void}> = ({ onClose, onCreate }) => {
    const [roomName, setRoomName] = useState("");
    const [selectedType, setSelectedType] = useState<RoomType>('fellowship');
    return (<div className="absolute inset-0 z-[80] bg-black/60 backdrop-blur-sm flex items-center justify-center p-6 animate-fade-in" onClick={onClose}><div className="bg-white w-full max-sm rounded-[32px] p-6 animate-scale-in relative shadow-2xl" onClick={e => e.stopPropagation()}><button onClick={onClose} className="absolute top-5 right-5 text-slate-400 hover:text-slate-600"><X size={22}/></button><div className="flex items-center mb-6"><div className="w-10 h-10 rounded-squircle bg-blue-600 flex items-center justify-center text-white mr-3 shadow-md shadow-blue-200"><Plus size={20} strokeWidth={3} /></div><h3 className="text-xl font-bold text-slate-900 tracking-tight">开启新房间</h3></div><div className="space-y-5"><div><label className="block text-xs font-bold text-slate-500 mb-3 ml-1 uppercase tracking-wider">选择房间主题</label><div className="grid grid-cols-2 gap-3">{(Object.keys(THEME_CONFIGS) as RoomType[]).map((type) => { const cfg = THEME_CONFIGS[type]; const isSelected = selectedType === type; return (<button key={type} onClick={() => setSelectedType(type)} className={`relative rounded-2xl p-3 flex items-center transition-all duration-200 border-2 text-left ${isSelected ? 'bg-blue-50 border-blue-500 shadow-sm' : 'bg-white border-slate-100 hover:border-slate-200 hover:bg-slate-50'}`}><div className={`w-10 h-10 rounded-squircle flex items-center justify-center mr-3 shrink-0 ${isSelected ? 'bg-blue-500 text-white' : 'bg-slate-100 text-slate-500'}`}><cfg.icon size={18} /></div><div><span className={`block text-sm font-bold ${isSelected ? 'text-blue-900' : 'text-slate-700'}`}>{cfg.label}</span></div></button>); })}</div></div><div><label className="block text-xs font-bold text-slate-500 mb-2 ml-1 uppercase tracking-wider">房间名称</label><div className="relative"><Edit3 size={18} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" /><input type="text" value={roomName} onChange={(e) => setRoomName(e.target.value)} className="w-full bg-slate-50 border-none rounded-2xl pl-11 pr-4 py-4 text-sm font-medium text-slate-900 placeholder:text-slate-400 focus:ring-2 focus:ring-blue-500 transition-all outline-none" placeholder="给房间起个好听的名字..." /></div></div><button onClick={() => { if (!roomName.trim()) return; onCreate(roomName, selectedType); }} disabled={!roomName.trim()} className="w-full bg-[#6366f1] hover:bg-[#4f46e5] text-white py-4 rounded-2xl font-bold text-base shadow-xl shadow-indigo-200 disabled:opacity-50 disabled:shadow-none transition-all active:scale-[0.98] mt-2 flex items-center justify-center">立即开启<ChevronRight size={18} className="ml-1 opacity-80" strokeWidth={3}/></button></div></div></div>);
};

export interface CommunityViewProps {
  activeVoiceRoom: Room | null;
  setActiveVoiceRoom: (room: Room | null) => void;
  isRoomMinimized: boolean;
  setIsRoomMinimized: (v: boolean) => void;
  isMicOn: boolean;
  setIsMicOn: (v: boolean) => void;
  myRoom: Room | null;
  setMyRoom: (room: Room | null) => void;
  posts: CommunityPost[];
  setPosts: (posts: CommunityPost[]) => void;
  onChatClick?: (contactId: string) => void;
  initialTab?: 'rooms' | 'feed' | 'directory' | 'prayer';
  unreadCount?: number;
  conversations: Conversation[];
  setConversations: (v: Conversation[]) => void;
}

const CommunityView: React.FC<CommunityViewProps> = ({
  activeVoiceRoom, setActiveVoiceRoom,
  isRoomMinimized, setIsRoomMinimized,
  isMicOn, setIsMicOn,
  myRoom, setMyRoom,
  posts, setPosts,
  onChatClick,
  initialTab = 'rooms',
  unreadCount = 0,
  conversations,
  setConversations
}) => {
  const staticRooms: Room[] = [
    { id: 'prayer_room', type: 'prayer', label: '祷告室', icon: HandHeart, color: 'text-rose-500', bg: 'bg-rose-50', desc: '早晨 6:00 - 7:00 | 每日晨更祷告会', action: 'voice', participants: 12 },
    { id: 'praise_room', type: 'praise', label: '赞美室', icon: Music, color: 'text-amber-500', bg: 'bg-amber-50', desc: '全天开放 | 诗歌敬拜与分享', action: 'voice', participants: 8 },
    { id: 'bible_reading', type: 'bible', label: '读经室', icon: BookOpen, color: 'text-blue-500', bg: 'bg-blue-50', desc: '研读《罗马书》 | 李教授带读', action: 'voice', participants: 25 },
    { id: 'preaching_room', type: 'preaching', label: '讲道室', icon: Mic2, color: 'text-purple-500', bg: 'bg-purple-50', desc: '主日信息分享 | 讲员：张院长', action: 'voice', participants: 45 },
    { id: 'fellowship_room', type: 'fellowship', label: '交通室', icon: Coffee, color: 'text-emerald-500', bg: 'bg-emerald-50', desc: '肢体交通，分享生活点滴与恩典。', action: 'voice' },
  ];

  const displayRooms = myRoom ? [myRoom, ...staticRooms] : staticRooms;
  const [activeTab, setActiveTab] = useState<'rooms' | 'feed' | 'directory' | 'prayer'>(initialTab);
  const [showCreateRoom, setShowCreateRoom] = useState(false);
  const [viewingUserProfile, setViewingUserProfile] = useState<{name: string, avatar: string, role: string, id: string} | null>(null);

  const handleCreateRoom = (name: string, type: RoomType, password?: string) => {
     const config = THEME_CONFIGS[type];
     const newRoom: Room = { id: `custom-${Date.now()}`, type, label: name, icon: config.icon, color: config.color, bg: config.bg, desc: config.desc, action: 'voice', participants: 1, isCustom: true, hostId: 'me', password };
     setMyRoom(newRoom);
     setActiveVoiceRoom(newRoom);
     setIsRoomMinimized(false);
     setShowCreateRoom(false);
  };

  return (
    <div className="min-h-screen bg-slate-50 pb-24 relative animate-fade-in">
        {showCreateRoom && <CreateRoomModal onClose={() => setShowCreateRoom(false)} onCreate={handleCreateRoom} />}
        {viewingUserProfile && <UserProfileModal user={viewingUserProfile} onClose={() => setViewingUserProfile(null)} onChat={(id) => onChatClick?.(id)} onViewFeed={() => {}} />}

        {/* Page Header */}
        <div className="bg-white sticky top-0 z-[50] border-b border-slate-100 shadow-sm pt-safe-top px-4">
            <div className="h-14 flex items-center justify-between">
                <div className="flex flex-col">
                    <h1 className="text-xl font-black text-slate-900 leading-none">校友圈</h1>
                    <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">AMAS COMMUNITY</p>
                </div>
                <div className="flex items-center space-x-2">
                    <button className="p-2 relative rounded-full hover:bg-slate-100"><Bell size={20} className="text-slate-700" /></button>
                    <button onClick={() => setViewingUserProfile({ id: 'me', name: MOCK_USER.name, avatar: MOCK_USER.avatar, role: MOCK_USER.degree })} className="w-8 h-8 rounded-squircle overflow-hidden border border-slate-200"><img src={MOCK_USER.avatar} className="w-full h-full object-cover" /></button>
                </div>
            </div>

            <div className="flex items-center space-x-1 py-1 -mx-2 overflow-x-auto scrollbar-hide">
                {['rooms', 'feed', 'prayer', 'directory'].map((tab) => (
                    <button key={tab} onClick={() => setActiveTab(tab as any)} className={`px-4 py-2 rounded-full text-xs font-black transition-all whitespace-nowrap ${activeTab === tab ? 'bg-blue-900 text-white shadow-lg' : 'text-slate-500'}`}>
                        {tab === 'rooms' ? '语音房间' : tab === 'feed' ? '动态广场' : tab === 'prayer' ? '代祷事项' : '校友录'}
                    </button>
                ))}
            </div>
        </div>

        {/* Rooms View */}
        {activeTab === 'rooms' && (
            <div className="p-4 space-y-4 animate-fade-in">
                <div className="flex items-center justify-between mb-2">
                    <h3 className="text-sm font-bold text-slate-800">热门讨论房间</h3>
                    <button onClick={() => setShowCreateRoom(true)} className="flex items-center text-xs font-bold text-blue-600 bg-blue-50 px-3 py-1.5 rounded-full"><Plus size={14} className="mr-1" strokeWidth={3} /> 发起房间</button>
                </div>
                <div className="grid grid-cols-1 gap-4">
                    {displayRooms.map((room) => (
                        <div key={room.id} onClick={() => { setActiveVoiceRoom(room); setIsRoomMinimized(false); }} className="bg-white rounded-[2rem] p-5 shadow-sm border border-slate-100 hover:shadow-md transition-all active:scale-[0.98] cursor-pointer group flex items-start">
                            <div className={`w-14 h-14 rounded-squircle flex items-center justify-center mr-4 shrink-0 shadow-sm border border-white ${room.bg} ${room.color}`}><room.icon size={28} /></div>
                            <div className="flex-1 min-w-0 pr-2">
                                <h4 className="font-bold text-slate-900 text-base truncate mb-1">{room.label}</h4>
                                <p className="text-xs text-slate-500 line-clamp-2">{room.desc}</p>
                            </div>
                            <div className="w-10 h-10 rounded-full bg-slate-50 text-blue-900 flex items-center justify-center group-hover:bg-blue-900 group-hover:text-white transition-all shadow-sm"><ArrowRight size={20} /></div>
                        </div>
                    ))}
                </div>
            </div>
        )}

        {/* Other tabs omitted for brevity, logic remains in App.tsx */}
    </div>
  );
};

