// --- Types ---
export type RoomType = 'prayer' | 'praise' | 'bible' | 'preaching' | 'fellowship';

export interface Room {
  id: string;
  type: RoomType;
  label: string;
  icon: any;
  color: string;
  bg: string;
  desc: string;
  announcement?: string;
  action: 'voice' | 'filter';
  participants?: number;
  isCustom?: boolean;
  hostId?: string; 
  password?: string;
}

export interface Liker { id: string; name: string; avatar: string; }
export interface Comment { id: string; userId: string; userName: string; content: string; userAvatar?: string; userRole?: string; }

export interface CommunityPost {
  id: string;
  userId: string;
  userName: string;
  userAvatar: string;
  userRole: string; 
  content: string;
