  commentList?: Comment[]; 
  category: string; 
  connectionStatus: 'none' | 'sent' | 'connected';
  sharedRoom?: Room;
  linkedCourseId?: string;
}

export interface Contact {
  id: string;
  name: string;
  role: string; 
  location?: string;
  avatar: string;
  status: 'none' | 'sent' | 'received' | 'connected';
}

export interface ChatMessage {
  id: string;
  user: string;
  userAvatar?: string;
  text: string;
  type?: 'text' | 'verse' | 'hymn' | 'gift' | 'system';
  giftData?: { name: string; icon: string; theme?: string };
}

export interface Conversation {
  id: string;
  userId: string;
  userName: string;
  userAvatar: string;
  isOnline: boolean;
  lastMessage: string;
  time: string;
  unread: number;
  role: string;
  isGroup?: boolean;
}

interface Participant {
  id: string;
  name: string;
  avatar: string;
  isSpeaking: boolean;
  role: 'host' | 'admin' | 'speaker' | 'listener';
}

