// Updated VoiceRoomOverlayProps to include missing properties used in App.tsx
export interface VoiceRoomOverlayProps {
  activeVoiceRoom: Room;
  isRoomMinimized: boolean;
  setIsRoomMinimized: (v: boolean) => void;
  setActiveVoiceRoom: (v: Room | null) => void;
  isMicOn: boolean;
  setIsMicOn: (v: boolean) => void;
  showToast: (msg: string) => void;
  onEndRoom: () => void;
  contacts?: Contact[];
  conversations?: Conversation[];
  initialChats?: any[];
  onUpdateRoom?: (room: Room) => void;
  onShareToFeed?: (room: Room, comment: string) => void;
  onViewProfile?: (user: { name: string; avatar: string; role: string; id: string }) => void;
  onChat?: (id: string) => void;
}

export const VoiceRoomOverlay: React.FC<VoiceRoomOverlayProps> = ({
  activeVoiceRoom, isRoomMinimized, setIsRoomMinimized, setActiveVoiceRoom,
  isMicOn, setIsMicOn, showToast, onEndRoom
}) => {
    const [showGuide, setShowGuide] = useState(true);
    const [isEditingContent, setIsEditingContent] = useState(false);
    const [content, setContent] = useState("此处显示房间核心信息...");
    const [participants] = useState<Participant[]>([
        { id: 'me', name: '我', avatar: MOCK_USER.avatar, isSpeaking: false, role: 'host' },
        { id: 'u1', name: '张大卫', avatar: 'https://picsum.photos/100/100?random=1', isSpeaking: false, role: 'speaker' },
        { id: 'u2', name: '陈恩惠', avatar: 'https://picsum.photos/100/100?random=2', isSpeaking: false, role: 'speaker' },
        { id: 'u3', name: '王以诺', avatar: 'https://picsum.photos/100/100?random=3', isSpeaking: false, role: 'speaker' },
        { id: 'u4', name: '李保罗', avatar: 'https://picsum.photos/100/100?random=4', isSpeaking: false, role: 'speaker' },
    ]);

    const isFellowship = activeVoiceRoom.type === 'fellowship';
    const stageParticipants = participants.filter(p => p.role !== 'listener').slice(0, 10);
    const leftParticipants = stageParticipants.slice(0, 5);
    const rightParticipants = stageParticipants.slice(5, 10);

    const getBgGradient = () => {
        switch(activeVoiceRoom.type) {
            case 'prayer': return 'from-[#2d0a15] to-black';
            case 'praise': return 'from-amber-950 to-black';
            case 'bible': return 'from-blue-950 to-black';
            case 'preaching': return 'from-purple-950 to-black';
            default: return 'from-slate-900 to-black';
        }
    };

    if (isRoomMinimized) {
        return createPortal(
            <div className="fixed bottom-20 right-4 z-[9999] animate-slide-up" onClick={() => setIsRoomMinimized(false)}>
                <div className="bg-slate-900/90 backdrop-blur-md text-white rounded-full px-4 py-2 shadow-2xl flex items-center border border-white/10">
                    <span className="relative flex h-2 w-2 mr-2">
                        <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-emerald-400 opacity-75"></span>
                        <span className="relative inline-flex rounded-full h-2 w-2 bg-emerald-500"></span>
                    </span>
                    <span className="text-[10px] font-bold">回到{activeVoiceRoom.label}</span>
                </div>
            </div>,
            document.body
        );
    }

    return createPortal(
      <div className={`fixed inset-0 z-[9999] bg-gradient-to-b ${getBgGradient()} flex flex-col text-white animate-fade-in`}>
        {showGuide && <RoomGuideModal type={activeVoiceRoom.type} onClose={() => setShowGuide(false)} />}

        {/* Header */}
        <div className="h-14 flex justify-between items-center px-4 pt-safe-top shrink-0">
          <button onClick={() => setIsRoomMinimized(true)} className="p-2"><Minimize2 size={20} /></button>
          <div className="text-center">
            <h2 className="font-bold text-xs">{activeVoiceRoom.label}</h2>
            <p className="text-[8px] text-emerald-400 font-bold uppercase tracking-widest">{participants.length}人在线</p>
          </div>
          <button onClick={onEndRoom} className="p-2 text-rose-400"><PhoneOff size={20} /></button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-hidden p-4 flex flex-col">
            {!isFellowship ? (
                <div className="flex-1 flex gap-4">
                    {/* Left Column */}
                    <div className="flex flex-col justify-between py-2 space-y-4">
                        {Array.from({length: 5}).map((_, i) => (
                            <div key={i} className="flex flex-col items-center relative">
                                {leftParticipants[i] ? (
                                    <div className={`relative w-12 h-12 p-[2px] rounded-squircle ${leftParticipants[i].id === 'me' ? 'bg-amber-400 shadow-lg' : 'bg-white/10'}`}>
                                        <img src={leftParticipants[i].avatar} className="w-full h-full rounded-squircle object-cover" />
                                        <div className="absolute -top-1 -right-1 bg-white/20 backdrop-blur rounded-full w-4 h-4 flex items-center justify-center text-[8px] font-bold">{i+1}</div>
                                    </div>
                                ) : (
                                    <div className="w-12 h-12 rounded-squircle border-2 border-dashed border-white/5 flex items-center justify-center text-white/5"><Mic size={16}/></div>
                                )}
                                <span className="text-[8px] opacity-40 mt-1 truncate max-w-[50px]">{leftParticipants[i]?.name || '等待上麦'}</span>
                            </div>
                        ))}
                    </div>

                    {/* Middle Card */}
                    <div className="flex-1 h-full bg-white/5 rounded-3xl border border-white/10 overflow-hidden flex flex-col shadow-2xl">
                         <div className="bg-white/5 px-4 py-2 flex items-center border-b border-white/5">
                            <span className="text-[10px] font-bold uppercase tracking-widest opacity-60">
                                {activeVoiceRoom.type === 'prayer' ? '代祷墙' : activeVoiceRoom.type === 'praise' ? '敬拜歌单' : activeVoiceRoom.type === 'bible' ? '共读圣经' : '讲道大纲'}
                            </span>
                         </div>
                         <div className="p-4 flex-1 overflow-y-auto custom-scrollbar">
                            {isEditingContent ? (
                                <textarea 
                                    autoFocus 
                                    value={content} 
                                    onChange={e => setContent(e.target.value)}
                                    onBlur={() => setIsEditingContent(false)}
                                    className="w-full h-full bg-transparent outline-none resize-none text-sm font-serif leading-relaxed"
                                />
                            ) : (
                                <div onClick={() => MOCK_USER.role === 'admin' && setIsEditingContent(true)} className="text-sm font-serif leading-relaxed opacity-80 whitespace-pre-wrap">
                                    {content}
                                </div>
                            )}
                         </div>
                    </div>

                    {/* Right Column */}
                    <div className="flex flex-col justify-between py-2 space-y-4">
                        {Array.from({length: 5}).map((_, i) => (
                            <div key={i} className="flex flex-col items-center relative">
                                {rightParticipants[i] ? (
                                    <div className="relative w-12 h-12 p-[2px] rounded-squircle bg-white/10">
                                        <img src={rightParticipants[i].avatar} className="w-full h-full rounded-squircle object-cover" />
                                        <div className="absolute -top-1 -right-1 bg-white/20 backdrop-blur rounded-full w-4 h-4 flex items-center justify-center text-[8px] font-bold">{i+6}</div>
                                    </div>
                                ) : (
                                    <div className="w-12 h-12 rounded-squircle border-2 border-dashed border-white/5 flex items-center justify-center text-white/5"><Mic size={16}/></div>
                                )}
                                <span className="text-[8px] opacity-40 mt-1 truncate max-w-[50px]">{rightParticipants[i]?.name || '等待上麦'}</span>
                            </div>
                        ))}
                    </div>
                </div>
            ) : (
                <div className="flex-1 grid grid-cols-3 gap-4 items-center justify-items-center py-6">
                    {stageParticipants.map(p => (
                        <div key={p.id} className="flex flex-col items-center">
                            <div className={`w-16 h-16 p-1 rounded-squircle border-2 ${p.isSpeaking ? 'border-emerald-400' : 'border-white/10'}`}>
                                <img src={p.avatar} className="w-full h-full rounded-squircle object-cover" />
                            </div>
                            <span className="text-[10px] mt-2 font-bold">{p.name}</span>
                        </div>
                    ))}
                </div>
            )}

            {/* Chat Area - Fixed to bottom */}
            <div className="h-40 shrink-0 mt-4 flex flex-col">
                <div className="flex-1 overflow-y-auto space-y-2 opacity-60 text-[10px] pb-2 scrollbar-hide" style={{maskImage: 'linear-gradient(to bottom, transparent, black 30%)'}}>
                    <div className="flex gap-2 items-start"><span className="font-bold text-blue-400">系统:</span><span>欢迎来到{activeVoiceRoom.label}。</span></div>
                    <div className="flex gap-2 items-start"><span className="font-bold text-rose-400">代祷者:</span><span>愿主与我们同在。</span></div>
                </div>
                <div className="flex items-center space-x-2 py-3 border-t border-white/5">
                    <div className="flex-1 bg-white/5 rounded-full px-4 h-10 flex items-center border border-white/10">
                        <input placeholder="想说点什么..." className="bg-transparent border-none outline-none text-xs w-full" />
                    </div>
                    <button onClick={() => setIsMicOn(!isMicOn)} className={`w-10 h-10 rounded-full flex items-center justify-center ${isMicOn ? 'bg-blue-600' : 'bg-white/5'}`}>
                        {isMicOn ? <Mic size={18}/> : <MicOff size={18}/>}
                    </button>
                    <button className="w-10 h-10 rounded-full bg-gradient-to-br from-amber-400 to-orange-600"><Gift size={18} className="mx-auto"/></button>
                </div>
            </div>
        </div>
      </div>,
      document.body
    );
};

// --- Community View ---

export interface CommunityViewProps {
  activeVoiceRoom: Room | null;
  setActiveVoiceRoom: (room: Room | null) => void;
  isRoomMinimized: boolean;
  setIsRoomMinimized: (v: boolean) => void;
  isMicOn: boolean;
  setIsMicOn: (v: boolean) => void;
  myRoom: Room | null;
  setMyRoom: (room: Room | null) => void;
  posts: CommunityPost[];
  setPosts: (posts: CommunityPost[]) => void;
  onChatClick?: (contactId: string) => void;
  initialTab?: 'rooms' | 'feed' | 'directory' | 'prayer';
  conversations: Conversation[];
  setConversations: (v: Conversation[]) => void;
  unreadCount?: number; // Added missing prop
}

const CommunityView: React.FC<CommunityViewProps> = ({
  activeVoiceRoom, setActiveVoiceRoom,
  isRoomMinimized, setIsRoomMinimized,
  isMicOn, setIsMicOn,
  myRoom, setMyRoom,
  posts, setPosts,
  onChatClick,
  initialTab = 'rooms',
  conversations,
}) => {
  const [activeTab, setActiveTab] = useState(initialTab);
  const [directoryTab, setDirectoryTab] = useState<'messages' | 'contacts'>('messages');

  const staticRooms: Room[] = useMemo(() => [
    { id: 'prayer_room', type: 'prayer', label: '祷告室', icon: HandHeart, color: 'text-rose-500', bg: 'bg-rose-50', desc: '早晨 6:00 - 7:00 | 每日晨更祷告会', action: 'voice', participants: 12 },
    { id: 'praise_room', type: 'praise', label: '赞美室', icon: Music, color: 'text-amber-500', bg: 'bg-amber-50', desc: '全天开放 | 诗歌敬拜与分享', action: 'voice', participants: 8 },
    { id: 'bible_reading', type: 'bible', label: '读经室', icon: BookOpen, color: 'text-blue-500', bg: 'bg-blue-50', desc: '研读《罗马书》 | 李教授带读', action: 'voice', participants: 25 },
    { id: 'preaching_room', type: 'preaching', label: '讲道室', icon: Mic2, color: 'text-purple-500', bg: 'bg-purple-50', desc: '主日信息分享 | 讲员：张院长', action: 'voice', participants: 45 },
    { id: 'fellowship_room', type: 'fellowship', label: '交通室', icon: Coffee, color: 'text-emerald-500', bg: 'bg-emerald-50', desc: '肢体交通，分享生活点滴与恩典。', action: 'voice' },
  ], []);

  return (
    <div className="min-h-screen bg-slate-50 pb-24 relative flex flex-col">
        {/* Sticky Header */}
        <div className="bg-white sticky top-0 z-[50] border-b border-slate-100 pt-safe-top px-4 shadow-sm shrink-0">
            <div className="h-14 flex items-center justify-between">
                <div>
                    <h1 className="text-xl font-black text-slate-900 leading-none">校友圈</h1>
                    <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">Community</p>
                </div>
                <button className="p-2 bg-slate-50 rounded-full"><Bell size={20} className="text-slate-700" /></button>
            </div>
            <div className="flex items-center space-x-1 py-1 -mx-2 overflow-x-auto scrollbar-hide">
                {['rooms', 'feed', 'prayer', 'directory'].map((tab) => (
                    <button key={tab} onClick={() => setActiveTab(tab as any)} className={`px-4 py-2 rounded-full text-xs font-black transition-all whitespace-nowrap ${activeTab === tab ? 'bg-blue-900 text-white' : 'text-slate-500'}`}>
                        {tab === 'rooms' ? '语音房间' : tab === 'feed' ? '动态广场' : tab === 'prayer' ? '代祷事项' : '校友录'}
                    </button>
                ))}
            </div>
        </div>

        {/* Tab Content */}
        <div className="flex-1 overflow-y-auto scrollbar-hide p-4">
            {activeTab === 'rooms' && (
                <div className="space-y-4 animate-fade-in">
                    <div className="flex justify-between items-center mb-2">
                        <h3 className="text-sm font-bold text-slate-800">活跃房间</h3>
                        <button className="text-xs font-bold text-blue-600 bg-blue-50 px-3 py-1.5 rounded-full">+ 开启房间</button>
                    </div>
                    {staticRooms.map(room => (
                        <div key={room.id} onClick={() => { setActiveVoiceRoom(room); setIsRoomMinimized(false); }} className="bg-white p-5 rounded-[2rem] border border-slate-100 shadow-sm flex items-start group active:scale-[0.98] transition-all">
                            <div className={`w-14 h-14 rounded-squircle flex items-center justify-center mr-4 border border-white ${room.bg} ${room.color}`}><room.icon size={28} /></div>
                            <div className="flex-1 min-w-0 pr-2">
                                <h4 className="font-bold text-slate-900 text-base truncate">{room.label}</h4>
                                <p className="text-xs text-slate-500 line-clamp-2">{room.desc}</p>
                            </div>
                            <div className="w-10 h-10 rounded-full bg-slate-50 flex items-center justify-center group-hover:bg-blue-900 group-hover:text-white transition-all"><ArrowRight size={20}/></div>
                        </div>
                    ))}
                </div>
            )}

            {activeTab === 'feed' && (
                <div className="space-y-6 animate-fade-in">
                    {posts.map(post => (
                        <div key={post.id} className="flex items-start gap-3">
                            <img src={post.userAvatar} className="w-10 h-10 rounded-squircle object-cover shrink-0" />
                            <div className="flex-1">
                                <div className="flex justify-between">
                                    <span className="text-sm font-bold text-blue-900">{post.userName}</span>
                                    <span className="text-[10px] text-slate-400">{post.timestamp}</span>
                                </div>
                                <p className="text-sm text-slate-700 mt-1 leading-relaxed">{post.content}</p>
                                <div className="flex items-center gap-4 mt-3 text-slate-400">
                                    <button className="flex items-center gap-1 text-[10px]"><Heart size={14}/> {post.likes}</button>
                                    <button className="flex items-center gap-1 text-[10px]"><MessageSquare size={14}/> {post.comments}</button>
                                </div>
                            </div>
                        </div>
                    ))}
                </div>
            )}

            {activeTab === 'prayer' && (
                <div className="space-y-4 animate-fade-in">
                    <div className="bg-rose-900 rounded-[2rem] p-6 text-white shadow-xl mb-6">
                        <h2 className="text-lg font-bold mb-2">国度代祷墙</h2>
                        <p className="text-[10px] opacity-80">同心合意的求，我在天上的父必为他们成全。</p>
                    </div>
                    <div className="bg-white p-6 rounded-[2rem] border border-slate-100 shadow-sm">
                        <h4 className="font-bold text-sm mb-2">为亚洲宣教事工祷告</h4>
                        <p className="text-xs text-slate-500 leading-relaxed">求主开启福音的大门，差遣更多工人进入庄稼熟了的禾场。</p>
                        <button className="w-full mt-4 py-2 bg-rose-50 text-rose-600 rounded-full text-[10px] font-bold">加入代祷 (128)</button>
                    </div>
                </div>
            )}

            {activeTab === 'directory' && (
                <div className="space-y-4 animate-fade-in">
                    <div className="flex bg-slate-100 p-1 rounded-2xl mb-4">
                        <button onClick={() => setDirectoryTab('messages')} className={`flex-1 py-2 text-[10px] font-black rounded-xl transition-all ${directoryTab === 'messages' ? 'bg-white text-blue-900 shadow-sm' : 'text-slate-500'}`}>消息</button>
                        <button onClick={() => setDirectoryTab('contacts')} className={`flex-1 py-2 text-[10px] font-black rounded-xl transition-all ${directoryTab === 'contacts' ? 'bg-white text-blue-900 shadow-sm' : 'text-slate-500'}`}>通讯录</button>
                    </div>
                    {directoryTab === 'messages' ? (
                        conversations.map(c => (
                            <div key={c.id} onClick={() => onChatClick?.(c.id)} className="flex items-center p-3 rounded-2xl bg-white border border-slate-100 group">
                                <img src={c.userAvatar} className="w-12 h-12 rounded-squircle mr-3" />
                                <div className="flex-1 min-w-0">
                                    <div className="flex justify-between"><h4 className="font-bold text-sm truncate">{c.userName}</h4><span className="text-[10px] text-slate-400">{c.time}</span></div>
                                    <p className="text-xs text-slate-500 truncate mt-0.5">{c.lastMessage}</p>
                                </div>
                            </div>
                        ))
                    ) : (
                        INITIAL_CONTACTS.map(contact => (
                            <div key={contact.id} className="flex items-center p-3 rounded-2xl bg-white border border-slate-100">
                                <img src={contact.avatar} className="w-10 h-10 rounded-squircle mr-3" />
                                <div className="flex-1">
                                    <h4 className="font-bold text-sm">{contact.name}</h4>
                                    <p className="text-[10px] text-slate-400 uppercase">{contact.role}</p>
                                </div>
                                <button onClick={() => onChatClick?.(contact.id)} className="p-2 bg-slate-50 rounded-full text-blue-600"><MessageSquare size={16}/></button>
                            </div>
                        ))
                    )}
                </div>
            )}
        </div>
    </div>
  );
};

export default CommunityView;
